<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Plus, Play, FolderOpen, RefreshCw } from 'lucide-vue-next'
import { mediaUrl } from '@/api'
import { tr } from '@/i18n'
import { useAuthStore } from '@/features/auth/authStore'
import { catalogApi, type CatalogResource } from './catalog'
import type { EditorMedia } from '@/features/video-editor/types'
const props=defineProps<{kind:'video'|'audio'|'sticker';readOnly:boolean}>(),emit=defineEmits<{select:[item:EditorMedia];add:[item:EditorMedia]}>()
const auth=useAuthStore(),items=ref<CatalogResource[]>([]),search=ref(''),keyword=ref(''),audioType=ref<'bgm'|'sound'>('bgm'),loading=ref(false),error=ref(''),page=ref(1),pages=ref(1)
const resourceKind=computed(()=>props.kind==='audio'?audioType.value:props.kind)
let sequence=0,disposed=false
function convert(item:CatalogResource):EditorMedia{return {key:`library:${item.id}`,source:{kind:'library',id:item.id},kind:props.kind,library_kind:item.kind,name:item.name,url:item.url,poster:item.poster_url,duration:item.duration,width:item.width,height:item.height}}
async function load(next=1){const version=++sequence;loading.value=true;error.value='';if(next===1)items.value=[];try{const response=await catalogApi.list({kind:resourceKind.value,search:keyword.value,page:next,origin:'team'});if(version===sequence&&!disposed){const rows=response.data.items.filter(i=>i.catalog==='media'&&i.state==='ready');items.value=next===1?rows:[...items.value,...rows];page.value=next;pages.value=response.data.pagination.pages}}catch(reason){if(version===sequence)error.value=reason instanceof Error?reason.message:tr('资源库加载失败')}finally{if(version===sequence)loading.value=false}}
watch(()=>[auth.activeTeamId,resourceKind.value],()=>{search.value='';keyword.value='';void load()},{immediate:true})
function refreshOnFocus(){void load()}
onMounted(()=>window.addEventListener('focus',refreshOnFocus))
onBeforeUnmount(()=>{disposed=true;++sequence;window.removeEventListener('focus',refreshOnFocus)})
</script>
<template><section class="team-resource-panel"><nav v-if="kind==='audio'"><button :aria-pressed="audioType==='bgm'" @click="audioType='bgm'">BGM</button><button :aria-pressed="audioType==='sound'" @click="audioType='sound'">{{tr('音效')}}</button></nav><form @submit.prevent="keyword=search.trim();load()"><input v-model="search" :placeholder="tr('搜索团队资源')" :aria-label="tr('搜索团队资源')"/><button type="submit" :aria-label="tr('搜索')"><RefreshCw :size="13"/></button></form><p v-if="loading" role="status">{{tr('正在加载资源…')}}</p><p v-if="error" role="alert">{{error}}</p><article v-for="item in items" :key="item.key"><button class="team-resource-preview" :aria-label="tr('预览 {p0}',{p0:item.name})" @click="emit('select',convert(item))"><img v-if="item.poster_url||kind==='sticker'" :src="mediaUrl(item.poster_url||item.url)" alt="" loading="lazy"/><Play v-else :size="18"/></button><div><strong>{{item.name}}</strong><small v-if="item.duration">{{item.duration.toFixed(1)}}s</small><small v-else>{{item.width}}×{{item.height}}</small></div><button :disabled="readOnly" :aria-label="tr('添加素材 {p0}',{p0:item.name})" @click="emit('add',convert(item))"><Plus :size="16"/></button></article><div v-if="!loading&&!items.length&&!error" class="team-resource-empty"><FolderOpen :size="25"/><span>{{tr('团队资源库暂无此类素材')}}</span></div><button v-if="error" @click="load()">{{tr('重新加载')}}</button><button v-if="page<pages" :disabled="loading" @click="load(page+1)">{{tr('加载更多')}}</button><RouterLink target="_blank" rel="noopener" :to="{path:'/resource-library',query:{kind:resourceKind,search:keyword||undefined}}">{{tr('管理团队资源')}}</RouterLink></section></template>
<style scoped>.team-resource-panel{display:grid;gap:12px;color:var(--app-text);font-size:11px}nav{display:flex;gap:15px}button{border:0;background:transparent;color:inherit;cursor:pointer;font:inherit;padding:5px}button:disabled{opacity:.4;cursor:not-allowed}button[aria-pressed=true]{color:var(--app-accent);border-bottom:1px solid var(--app-accent)}form{display:flex;align-items:center;border:1px solid var(--app-border);border-radius:6px;overflow:hidden}form input{min-width:0;width:100%;height:32px;border:0!important;background:var(--app-surface)!important;color:var(--app-text);padding:0 8px}article{display:flex;align-items:center;gap:8px;min-width:0}.team-resource-preview{width:50px;height:42px;padding:0;background:var(--app-surface-muted);border:1px solid var(--app-border);border-radius:5px;flex-shrink:0;overflow:hidden;display:grid;place-items:center;color:var(--app-accent)}img{width:100%;height:100%;object-fit:contain}article>div{min-width:0;flex:1}strong{display:block;font-size:11px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}small{display:block;color:var(--app-text-secondary);font-size:10px;margin-top:6px}.team-resource-empty{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;min-height:130px;color:var(--app-text-secondary)}a{font-size:10px;color:var(--app-accent);text-decoration:none;margin-top:8px}p{font-size:11px;color:var(--app-text-secondary)}[role=alert]{color:var(--app-danger)}</style>
